<template><div class="app-page"><div class="app-page-inner-wide"><section class="app-page-header"><h1 class="app-title">{{ t('reports.title') }}</h1></section><div v-if="error" class="border border-rose-200 bg-rose-50 px-4 py-3 text-sm text-rose-700 dark:border-rose-900 dark:bg-rose-950/30 dark:text-rose-200">{{ error }}</div><div class="grid gap-5 xl:grid-cols-[20rem_minmax(0,1fr)]"><aside class="space-y-5"><section class="app-panel p-5"><h2 class="app-section-title">{{ t('reports.generate') }}</h2><form class="mt-4 space-y-3" @submit.prevent="generate"><label class="space-y-1"><span class="label">{{ t('reports.type') }}</span><select v-model="form.reportType" class="app-control w-full"><option value="daily_brief">{{ t('reports.types.daily_brief') }}</option><option value="weekly_brief">{{ t('reports.types.weekly_brief') }}</option><option value="asset_review">{{ t('reports.types.asset_review') }}</option><option value="portfolio_review">{{ t('reports.types.portfolio_review') }}</option><option value="decision_review">{{ t('reports.types.decision_review') }}</option></select></label><label class="space-y-1"><span class="label">{{ t('reports.reportTitle') }}</span><input v-model.trim="form.title" class="app-control w-full" required /></label><label v-if="form.reportType==='asset_review'" class="space-y-1"><span class="label">{{ t('reports.symbol') }}</span><input v-model.trim="form.symbol" class="app-control w-full" placeholder="BTC/USDT" required /></label><label class="space-y-1"><span class="label">{{ t('reports.portfolio') }} <span v-if="form.reportType!=='portfolio_review'" class="app-muted">({{ t('reports.optional') }})</span></span><select v-model="form.portfolioId" class="app-control w-full" :required="form.reportType==='portfolio_review'"><option value="">{{ t('reports.useActivePortfolio') }}</option><option v-for="item in portfolios" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><button type="submit" class="app-button-primary w-full" :disabled="generating">{{ generating?t('reports.generating'):t('reports.generateNow') }}</button></form></section><section class="app-panel"><div class="app-panel-header flex items-center justify-between"><h2 class="app-section-title">{{ t('reports.saved') }}</h2><label class="text-xs app-muted"><input v-model="includeArchived" type="checkbox" @change="load" /> {{ t('reports.archived') }}</label></div><div class="max-h-[36rem] overflow-y-auto p-3"><button v-for="item in reports" :key="item.id" type="button" class="mb-2 w-full border-l-2 px-3 py-3 text-left" :class="selected?.id===item.id?'border-emerald-700 bg-emerald-50 dark:bg-emerald-950/20':'border-transparent hover:bg-stone-50 dark:hover:bg-slate-700/30'" @click="selected=item"><span class="block font-semibold">{{ item.title }}</span><span class="mt-1 block text-xs app-muted">{{ dateTime(item.createdAt) }}</span></button><p v-if="!reports.length" class="p-5 text-sm app-muted">{{ t('reports.empty') }}</p></div></section></aside><main><section v-if="selected" class="app-panel overflow-hidden"><div class="app-panel-header flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><h2 class="text-xl font-semibold">{{ selected.title }}</h2><p class="mt-1 text-xs app-muted">{{ selected.reportType }} · {{ dateTime(selected.createdAt) }}</p></div><div class="flex flex-wrap gap-2"><button type="button" class="app-button-secondary" @click="download('md')">Markdown</button><button type="button" class="app-button-secondary" @click="download('json')">JSON</button><button type="button" class="app-button-secondary" @click="toggleArchive">{{ selected.archivedAt?t('reports.restore'):t('reports.archive') }}</button></div></div><pre class="whitespace-pre-wrap break-words p-6 font-sans text-sm leading-7 text-stone-800 dark:text-slate-200">{{ selected.contentMarkdown }}</pre></section><section v-else class="app-panel p-12 text-center app-muted">{{ t('reports.choose') }}</section></main></div></div></div></template>
<script setup lang="ts">import { onMounted,reactive,ref } from 'vue';import { useI18n } from 'vue-i18n';import { researchApi } from '@/modules/research';import { toolsApi } from '@/modules/tools';import type { ResearchReportResponse } from '@/modules/research/contracts';import type { PortfolioBalancePortfolio } from '@/modules/tools/contracts';const {t}=useI18n();const reports=ref<ResearchReportResponse[]>([]),selected=ref<ResearchReportResponse|null>(null),portfolios=ref<PortfolioBalancePortfolio[]>([]);const includeArchived=ref(false),generating=ref(false),error=ref('');const form=reactive({reportType:'daily_brief' as 'daily_brief'|'weekly_brief'|'asset_review'|'portfolio_review'|'decision_review',title:'',symbol:'',portfolioId:''});const load=async()=>{try{const [reportPage,collection]=await Promise.all([researchApi.listReports(includeArchived.value),toolsApi.getPortfolioCollection()]);reports.value=reportPage.items||[];portfolios.value=collection.snapshot.portfolios||[];if(selected.value)selected.value=reports.value.find(v=>v.id===selected.value?.id)||null}catch(e){error.value=e instanceof Error?e.message:String(e)}};const generate=async()=>{generating.value=true;error.value='';try{selected.value=await researchApi.generateReport({title:form.title,reportType:form.reportType,symbol:form.reportType==='asset_review'?form.symbol:null,portfolioId:form.portfolioId||null});await load()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{generating.value=false}};const toggleArchive=async()=>{if(!selected.value)return;selected.value=await researchApi.setReportArchived(selected.value.id,selected.value.version,!selected.value.archivedAt);await load()};const download=(kind:'md'|'json')=>{if(!selected.value)return;const content=kind==='md'?selected.value.contentMarkdown:JSON.stringify(selected.value.dataSnapshot,null,2);const url=URL.createObjectURL(new Blob([content],{type:kind==='md'?'text/markdown;charset=utf-8':'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`opentrading-report-${selected.value.id}.${kind}`;a.click();URL.revokeObjectURL(url)};const dateTime=(v:string)=>new Date(v).toLocaleString();onMounted(load)</script>
